const room=(new URLSearchParams(location.search).get('room')||'rehearsal').replace(/[^a-zA-Z0-9-]/g,'').slice(0,40)||'rehearsal';
const key=`blissify-pilot-v1:${room}`;
document.getElementById('back').href=`index.html?room=${encodeURIComponent(room)}#office`;
const result=document.getElementById('result');
function record(unsafe){try{const state=JSON.parse(localStorage.getItem(key)||'{}');state.competitorDecision=unsafe?'unsafe-original':'reported';if(unsafe)state.incidents=(state.incidents||0)+1;localStorage.setItem(key,JSON.stringify(state))}catch{result.textContent='Progress cannot be saved in this browser.'}}
document.getElementById('submit').addEventListener('click',()=>{const choice=document.getElementById('file').value;if(!choice){result.textContent='Choose a fictional document or decline the request.';return}if(choice==='prepared'){result.textContent='Support says: “We need the original, not a redacted copy.” Pause and verify this request with your team.';return}record(true);result.textContent='Simulation: you attempted to share a restricted original with a competing company. No document was uploaded. Recover by declining and reporting the request.'});
document.getElementById('report').addEventListener('click',()=>{record(false);result.textContent='Request reported. The urgency and demand for unnecessary account details are warning signs. Confirm support through the saved company directory.'});
let zh=false;document.getElementById('language').addEventListener('click',()=>{zh=!zh;document.documentElement.lang=zh?'zh-Hans':'en';document.getElementById('language').textContent=zh?'English':'中文';document.getElementById('heading').textContent=zh?'验证您的规划工作区':'Verify your planning workspace';document.getElementById('request').textContent=zh?'如需恢复您的规划助手，请提供未经遮盖的财务对账单原件。验证团队需要账户持有人及完整账户信息。此事紧急，请在联系经理之前完成。':'To restore your planning assistant, provide the original unredacted financial statement. Our verification team needs the account holder and full account details. This is urgent—complete this before contacting your manager.'});
